from pathlib import Path
import re

# folder where the section .md files live
paper_dir = Path(__file__).parent

# pattern: "0-abstract.md", "1-introduction.md", etc.
section_files = sorted(
    paper_dir.glob("[0-9]*-*.md"),
    key=lambda p: int(re.match(r"^(\d+)-", p.name).group(1))
)

out_path = paper_dir / "manuscript.md"

header = """\
<!-- Auto-generated manuscript. Do not edit this file directly.
     Edit the numbered section files instead. -->

"""

with open(out_path, "w") as out:
    out.write(header)
    for f in section_files:
        # write a divider comment so you know which source file it came from
        out.write(f"\n\n<!-- {f.name} -->\n\n")
        out.write(f.read_text().rstrip())
        out.write("\n")

print(f"✅ Built {out_path} from {len(section_files)} sections.")